sec_views={"title":"آراء العلماء في الأهرام","banner":"/architecture/banners/b4.webp","blocks":[
{"h":"أحمد فخري"},
v("يرى أحمد فخري أن الهرم الأكبر ليس سوى مقبرة، ويرفض النظريات الغامضة التي نسبت إليه أغراضًا أخرى، ومنها آراء بيازي سميث وأتباعه. ويقول إن البحث الأثري يثبت أنه مقبرة الملك خوفو، لكنه يقر بأن مشكلات طريقة البناء لم تُحل كلها (ص179 و180).",[F]),
v("ويشرح في الفصل الثاني كيف كان يُختار موضع الهرم: الضفة الغربية للنيل لأنها أرض الموتى، وهضبة قريبة من منف، وارتفاع يقارب 65 مترًا، وقرب من المحاجر، وسهولة في شق طريق صاعد. وكان كبار الموظفين يشرفون على العمل ويزور الملك الموقع (ص19 و20).",[F]),
v("ويستدل على طريقة رفع الأحجار بالهرم المدرج غير المكتمل في سقارة (هرم سخم خت)، فآثار الطرق المصنوعة من الرمل والأنقاض وجدرانها من اللبن تدل على أن البنائين استعملوا المنحدرات، وأن الطريقة نفسها استُعملت في الأهرام على الأرجح. وهذا استنتاج منه وليس نصًا قديمًا. وكانت الأحجار الثقيلة تُجر على زلاجات، ويُصب سائل أمامها (ص23 و24). ونُقل حجر أسوان بالمراكب (ص19).",[F]),
{"h":"مصطفى وزيري"},
v("قال مصطفى وزيري، حين كان رئيس المجلس الأعلى للآثار، إن الأهرامات مقابر ملكية، وإن عددها 124 هرمًا في مصر، وإن أشهرها وأقدمها هرم زوسر في سقارة وهو أقدم بناء حجري عرفته البشرية. وقال إن بقايا الممر الصاعد تدل على أن الكتل نُقلت على زلاجات خشبية، وإن مداخل الأهرام كلها في الشمال لأن المصري القديم اعتقد أن روح الميت تعود إلى المقبرة ليلًا عن طريق النجم القطبي الشمالي. وهذه أقوال شفهية في مناسبة عامة، نقلتها الصحافة.",[WA]),
v("وقال بصفته الأمين العام للمجلس الأعلى للآثار إن الزلازل لا تؤثر في الأهرامات بسبب طريقة بنائها وقاعدتها الكبيرة، وإنها لا تؤثر في أبو الهول لأنه جزء من كتلة صخرية في الأرض. وهذه أقوال إعلامية ولم نجد بحثًا مكتوبًا له بهذه الصيغة.",[WB]),
{"h":"حسين عبد البصير"},
v("يرى حسين عبد البصير أن أهرامات الجيزة كانت قمة التطور في حياة المصري القديم، وأن المصري القديم كان شديد الملاحظة للطبيعة ومنها فيضان النيل، وأنه رأى بعد الفيضان كتلة ترتفع من الأرض فأخذ منها الفكرة الهرمية. ويقول إن فكرة الهرم المدرج جاءت من زوسر وإمحوتب، وإن هرم سقارة أول هرم في تاريخ العالم وأقدم بناء حجري. وهذا تفسير شخصي لأصل الفكرة وليس نصًا قديمًا.",[AB1]),
v("وفي مقال له يقول إن الأهرامات بُنيت مقابر ملكية، ويرد على الادعاء بأنها محطات طاقة بأن حولها معابد جنائزية ومعابد وادٍ وطرقًا صاعدة ومصاطب للنبلاء ومقابر العمال، وبأن أوراق وادي الجرف (يوميات مرر) تسجل نقل الأحجار من محاجر طرة إلى موقع هرم خوفو، وبأن نصوص الأهرام تصف رحلة الملك إلى العالم الآخر.",[AB2]),
{"badge":"d","p":"بين هؤلاء العلماء اتفاق على أن الأهرام مقابر ملكية. أما أصل فكرة الهرم وطريقة رفع الأحجار فقد عرضها كل منهم بقدر مختلف، ووزارة الآثار نفسها تقول إنه لا توجد حتى اليوم معلومات مؤكدة عن الطريقة التي بُني بها الهرم الأكبر.","cite":[MG]},
]}
sec_dah={"title":"أهرام سنفرو في دهشور وميدوم","banner":"/architecture/banners/b3.webp","blocks":[
{"h":"الهرم المنحني"},
v("تقول وزارة السياحة والآثار إن الهرم المنحني من بناء الملك سنفرو، أول ملوك الأسرة الرابعة، وإنه سُمّي منحنيًا لتغيير زاوية البناء، فقد بدأ بزاوية 55 درجة ثم عُدّلت إلى 43 درجة بسبب الحمل الزائد على الأحجار. وتعدّه مرحلة انتقالية بين الهرم المدرج في سقارة والأهرام كاملة الشكل في الجيزة، وتقول إن مهندسي الملك بنوا بعده الهرم الأحمر إلى الشمال منه. وله مدخلان، شمالي وغربي، يؤدي كل منهما إلى غرفة ذات سقف متدرج.",[MB]),
v("ويصف أحمد فخري معبد الوادي للهرم الجنوبي بأنه أقدم معبد وادٍ كُشف حتى الآن، وهو بناء مستطيل من اللبن عليه سور سميك وبوابة ضخمة في الجدار الشرقي، ويبدأ منه طريق صاعد بين سورين من اللبن. ويذكر أن الكشف عنه أخرج نحو 1400 قطعة من النقوش، وأن هذا يغيّر الاعتقاد الذي ساد زمنًا طويلًا بأن جدران المعابد لم تُزيَّن بالنقوش قبل نهاية الأسرة الرابعة (ص120 و121).",[F]),
{"h":"هرم ميدوم"},
v("يقول فخري إن هرم ميدوم تنسب بنايته إلى الملك «حوني»، وإن الأرجح أن سنفرو هو الذي أتمّه. وإنه لا يستطيع الجزم بأن سنفرو هو الذي أدخل فكرة معبد الوادي، أو أنه قلّد طرازًا معماريًا معروفًا قبله لم يُعثر على بقاياه (ص121).",[F]),
{"badge":"d","p":"نسبة هرم ميدوم إلى حوني أو سنفرو محل خلاف في الكتب، وقد نقلنا هنا موقف فخري كما قرأناه ولا نحكم بينهما.","cite":[F]},
]}
sec_work={"title":"مدينة بناة الأهرام","banner":"/architecture/banners/b5.webp","blocks":[
v("تقول وزارة السياحة والآثار إن بقايا تجمع سكني كبير تسمى «حيط الغراب» اكتُشفت في الجنوب الشرقي لهضبة الجيزة، وإن فيه عاش ومات العمال الذين بنوا المجموعتين الهرميتين لخفرع ومنكاورع، مع بقايا أقدم من عهد خوفو. وظهرت فيه بيوت ومخازن وثلاثة شوارع رئيسية ومبنى إداري ملكي وأربع صالات كبيرة يُحتمل أنها كانت ثكنات للنوم وإعداد الطعام. وعُثر على عظام أسماك وطيور وأبقار وأغنام وماعز وخنازير، وتستنتج الوزارة من ذلك أن الدولة كانت تتكفل برعاية العمال.",[MW]),
v("وعلى سفح التل غرب المدينة جبانة دُفن فيها مشرفون من الرتب الدنيا في مصاطب متواضعة من اللبن، ودُفن كبار المشرفين والحرفيون المهرة والفنانون في مصاطب حجرية أعلى المنحدر. وذكرت الوزارة منها مقبرة المشرف على صناعة الكتان نفرثيث.",[MW]),
v("ويستشهد حسين عبد البصير بمقابر العمال قرب الهضبة دليلًا على أن بناة الهرم مصريون عاشوا وماتوا هناك.",[AB2]),
]}
sec_tem={"title":"المعابد الكبرى: الكرنك والدير البحري وأبو سمبل","banner":"/architecture/banners/b6.webp","blocks":[
{"h":"الكرنك"},
v("تقول وزارة السياحة والآثار إن اسمه القديم «إبت سوت»، أي أكثر الأماكن تميزًا، وإنه على الضفة الشرقية للنيل في طيبة (الأقصر). وكانت تُقام في معبد آمون الكبير طقوس المعبود آمون. واهتم الملوك بالمعبد من عهد إنتف الثاني (نحو 2112 إلى 2063 ق.م) حتى العصر البطلمي، مع إضافات في العصر الروماني. وبُني المعبد على محور شرقي غربي يحاكي رحلة الشمس في السماء، وله محور شمالي جنوبي يربطه بمعبد الأقصر.",[MK]),
{"h":"معبد الدير البحري"},
v("تقول الوزارة إن الملكة حتشبسوت (نحو 1473 إلى 1458 ق.م) بنت معبدها في الدير البحري على الضفة الغربية قبالة الكرنك، وإن اسمه المصري القديم «جسر جسرو» أي أقدس المقدسات، وإن سننموت صممه وحمل ألقابًا منها مدير أملاك آمون. وللمعبد ثلاثة مستويات في كل منها صف أعمدة، وهو معبد جنائزي فيه أجزاء مخصصة لوالدها تحتمس الأول وللمعبودة حتحور وللمعبود أنوبيس، ومقصورة مكشوفة لمعبود الشمس. وفي جدرانه مناظر نقل المسلات من المحاجر إلى الكرنك، وبعثة حتشبسوت إلى بلاد بونت.",[MH]),
{"h":"أبو سمبل"},
v("تقول الوزارة إن المعبد الكبير في النوبة بناه رمسيس الثاني من الأسرة التاسعة عشرة ونُحت كله في الجبل نحو 1264 ق.م، وإن واجهته أربعة تماثيل ضخمة جالسة سقط أحدها بزلزال قديم. وتدخل أشعة الشمس إلى المعبد يومين في السنة، 22 فبراير و22 أكتوبر، فتضيء التماثيل في العمق إلا المعبود بتاح. وإلى الشمال المعبد الصغير للمعبودة حتحور والملكة نفرتاري. ونُقل المعبدان عام 1968 بعد بناء السد العالي بجهود دولية قادتها اليونسكو، وسُجّل الموقع في قائمة التراث العالمي عام 1979.",[MA]),
v("وتذكر محافظة القاهرة أن أعمال نقل معبد أبو سمبل انتهت يوم 22 سبتمبر 1968.",[MC]),
{"badge":"u","p":"لم نقارن تواريخ بناء هذه المعابد بكتب علماء مصريين بعد، فهي كما ذكرتها الوزارة."},
]}
